SELECT lives_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),10,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-01'),0,NULL,DATE '2026-08-01',NULL,' ex-001 ') $$,'Owner creates contractor-level exchange draft');
SELECT results_eq($$ SELECT ce.reference::text, ce.source_amount, ce.destination_amount, ce.rounding_result, ce.fee_amount, ce.fee_currency_code IS NULL, ce.fee_account_id IS NULL, fe.project_id IS NULL, fe.client_id IS NULL, ft.reporting_currency_code, fe.version_number FROM app.currency_exchanges ce JOIN app.financial_events fe ON fe.id=ce.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE ce.reference='EX-001' $$,$$ VALUES ('EX-001'::text,10::numeric,37.55::numeric,0::numeric,0::numeric,true,true,true,true,'USD'::bpchar,1) $$,'contractor draft normalizes reference, derives destination and saves contractor reporting currency');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='EX-001'),0,'draft exchange has no ledger entries');
SELECT throws_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),10,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-01'),0,NULL,DATE '2026-08-01',NULL,'EX-001') $$,'23505','Duplicate currency exchange.','duplicate exchange denied');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),1,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-01'),0,NULL,DATE '2026-08-01',NULL,NULL) $$,'null reference exchange allowed');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),1,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-01'),0,NULL,DATE '2026-08-01',NULL,' ') $$,'blank reference exchange allowed again because event number enters fingerprint');
SELECT ok((SELECT bool_and(fe.duplicate_fingerprint LIKE '%event_number=FE-%') FROM app.currency_exchanges ce JOIN app.financial_events fe ON fe.id=ce.financial_event_id WHERE ce.reference IS NULL),'null-reference exchange fingerprints include event number');
SELECT throws_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Fee 80'),1,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-01'),0,NULL,DATE '2026-08-01',NULL,'BAD-SAME') $$,'23514','Invalid currency exchange.','same source and destination currency denied');
SELECT throws_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),1,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-02'),0,NULL,DATE '2026-08-01',NULL,'BAD-DATE') $$,'23514','Invalid currency exchange rate.','rate must match exchange date');
SELECT throws_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange YER 80'),1,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-01'),0,NULL,DATE '2026-08-01',NULL,'BAD-PAIR') $$,'23514','Invalid currency exchange rate.','rate direction must cover source and destination pair');

SELECT throws_ok($$ SELECT * FROM public.server_owner_update_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='EX-001'),0,(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),11,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-01'),0,NULL,DATE '2026-08-01',NULL,'EX-002') $$,'40001','Currency exchange version conflict.','stale update denied');
UPDATE app.contractor_profiles SET default_reporting_currency_code='SAR' WHERE singleton_key=1;
SELECT lives_ok($$ SELECT * FROM public.server_owner_update_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='EX-001'),1,(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),11,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-01'),0,NULL,DATE '2026-08-01',NULL,'EX-002') $$,'draft update works');
SELECT results_eq($$ SELECT ce.source_amount, ce.destination_amount, ce.reference::text, fe.version_number, ft.reporting_currency_code FROM app.currency_exchanges ce JOIN app.financial_events fe ON fe.id=ce.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE ce.reference='EX-002' $$,$$ VALUES (11::numeric,41.31::numeric,'EX-002'::text,2,'USD'::bpchar) $$,'update recalculates destination with ROUND_HALF_UP and preserves reporting currency');
SELECT is((SELECT ft.reporting_currency_code FROM app.currency_exchanges ce JOIN app.financial_transactions ft ON ft.financial_event_id=ce.financial_event_id WHERE ce.reference='EX-002'),'USD'::bpchar,'draft update does not drift saved reporting currency to changed contractor default');
UPDATE app.contractor_profiles SET default_reporting_currency_code='SAR' WHERE singleton_key=1;
