UPDATE app.contractor_profiles SET default_reporting_currency_code='USD' WHERE singleton_key=1;

SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='EX-002'),2) $$,'Owner submits exchange');
SELECT results_eq($$ SELECT fe.status::text, ft.status::text, fe.version_number FROM app.currency_exchanges ce JOIN app.financial_events fe ON fe.id=ce.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE ce.reference='EX-002' $$,$$ VALUES ('SUBMITTED'::text,'SUBMITTED'::text,3) $$,'submit moves parent lifecycle');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'))),100::numeric,'submitted exchange has no source balance effect');
SELECT throws_ok($$ SELECT * FROM public.server_owner_approve_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='EX-002'),3) $$,'42501','Currency exchange requires different Owner approval.','self approval denied');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_currency_exchange('00000000-0000-0000-0000-000000008002',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='EX-002'),3) $$,'different Owner approves exchange');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='EX-002'),4,'no-fee approval posts exactly four ledger entries');
SELECT results_eq($$ SELECT le.line_no, CASE WHEN la.financial_account_id=(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80') THEN 'DEST-ASSET' WHEN la.financial_account_id=(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80') THEN 'SOURCE-ASSET' ELSE la.code::text END, le.currency_code, le.debit_amount, le.credit_amount, le.reporting_debit_amount, le.reporting_credit_amount, le.rounding_adjustment FROM app.ledger_entries le JOIN app.ledger_accounts la ON la.id=le.ledger_account_id JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='EX-002' ORDER BY le.line_no $$,$$ VALUES (1,'DEST-ASSET'::text,'SAR'::bpchar,41.31::numeric,0::numeric,11::numeric,0::numeric,0::numeric),(2,'CTRL-FX-CLEARING-SAR'::text,'SAR'::bpchar,0::numeric,41.31::numeric,0::numeric,11::numeric,0.005000::numeric),(3,'CTRL-FX-CLEARING-USD'::text,'USD'::bpchar,11::numeric,0::numeric,11::numeric,0::numeric,0::numeric),(4,'SOURCE-ASSET'::text,'USD'::bpchar,0::numeric,11::numeric,0::numeric,11::numeric,0::numeric) $$,'no-fee ledger lines and signed rounding adjustment are exact');
SELECT results_eq($$ SELECT code::text, normal_side::text, account_kind::text, financial_account_id IS NULL FROM app.ledger_accounts WHERE code IN ('CTRL-FX-CLEARING-USD','CTRL-FX-CLEARING-SAR') ORDER BY code $$,$$ VALUES ('CTRL-FX-CLEARING-SAR'::text,'DEBIT'::text,'CONTROL'::text,true),('CTRL-FX-CLEARING-USD'::text,'DEBIT'::text,'CONTROL'::text,true) $$,'FX clearing controls are private system debit-normal controls');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'))),89::numeric,'source account decreases by source amount');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'))),41.31::numeric,'destination account increases by rounded destination amount');
SELECT is((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange Unrelated 80'))),0::numeric,'unrelated account unchanged');
SELECT results_eq($$ SELECT sum(reporting_debit_amount), sum(reporting_credit_amount) FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='EX-002' $$,$$ VALUES (22::numeric,22::numeric) $$,'conversion reporting effect nets to zero');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_currency_exchange('00000000-0000-0000-0000-000000008002',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='EX-002'),4) $$,'approval retry is idempotent');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='EX-002'),4,'idempotent approval does not duplicate lines');
SELECT is((SELECT count(*)::integer FROM app.activity_logs WHERE action='currency_exchange_transaction_posted'),1,'idempotent approval does not duplicate posting activity');
SELECT throws_ok($$ SELECT * FROM public.server_owner_update_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='EX-002'),4,(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),12,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-01'),0,NULL,DATE '2026-08-01',NULL,'AFTER') $$,'23514','Currency exchange cannot be updated.','posted exchange immutable through workflow');
SELECT throws_ok($$ UPDATE app.currency_exchanges SET source_amount=99 WHERE reference='EX-002' $$,'23514','Currency exchanges require trusted functions.','direct exchange update denied');
SELECT throws_ok($$ DELETE FROM app.currency_exchanges WHERE reference='EX-002' $$,'23514','Currency exchanges cannot be deleted.','direct exchange delete denied');

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),37.50,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-02'),0,NULL,DATE '2026-08-02',NULL,'DIVIDE') $$,'reverse direction exchange draft uses quote-to-base division');
SELECT results_eq($$ SELECT source_amount, destination_amount, rounding_result FROM app.currency_exchanges WHERE reference='DIVIDE' $$,$$ VALUES (37.50::numeric,10.00::numeric,0::numeric) $$,'canonical divide direction derives destination amount');

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),10,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-03'),2,NULL,DATE '2026-08-03',NULL,'FEE-SOURCE') $$,'positive fee defaults to source account');
SELECT results_eq($$ SELECT fee_amount, fee_currency_code, fee_account_id=(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80') FROM app.currency_exchanges WHERE reference='FEE-SOURCE' $$,$$ VALUES (2::numeric,'USD'::bpchar,true) $$,'source-account default fee stored with source currency');
SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='FEE-SOURCE'),1) $$,'source-fee exchange submitted');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_currency_exchange('00000000-0000-0000-0000-000000008002',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='FEE-SOURCE'),2) $$,'source-fee exchange approved');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='FEE-SOURCE'),6,'fee approval posts exactly six ledger entries');
SELECT results_eq($$ SELECT le.line_no, CASE WHEN la.code='CTRL-FX-FEE-USD' THEN la.code::text WHEN la.financial_account_id=(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80') THEN 'SOURCE-ASSET' ELSE la.code::text END, le.debit_amount, le.credit_amount FROM app.ledger_entries le JOIN app.ledger_accounts la ON la.id=le.ledger_account_id JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='FEE-SOURCE' AND le.line_no IN (5,6) ORDER BY le.line_no $$,$$ VALUES (5,'CTRL-FX-FEE-USD'::text,2::numeric,0::numeric),(6,'SOURCE-ASSET'::text,0::numeric,2::numeric) $$,'fee lines debit fee control and credit effective fee asset');
SELECT results_eq($$ SELECT code::text, normal_side::text, account_kind::text FROM app.ledger_accounts WHERE code='CTRL-FX-FEE-USD' $$,$$ VALUES ('CTRL-FX-FEE-USD'::text,'DEBIT'::text,'CONTROL'::text) $$,'FX fee control is debit-normal system control');
SELECT throws_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),1,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-03'),1,(SELECT id FROM app.financial_accounts WHERE name='Exchange YER 80'),DATE '2026-08-03',NULL,'BAD-FEE') $$,'23514','Invalid currency exchange fee.','fee account currency must be source or destination');

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),5,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-04'),1,(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Fee 80'),DATE '2026-08-04',(SELECT id FROM app.projects WHERE name='Project 80'),'PROJECT-FEE') $$,'project-associated fee exchange draft created');
SELECT results_eq($$ SELECT fe.project_id=(SELECT id FROM app.projects WHERE name='Project 80'), fe.client_id=(SELECT client_id FROM app.projects WHERE name='Project 80'), ft.reporting_currency_code, ce.fee_account_id=(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Fee 80') FROM app.currency_exchanges ce JOIN app.financial_events fe ON fe.id=ce.financial_event_id JOIN app.financial_transactions ft ON ft.financial_event_id=fe.id WHERE ce.reference='PROJECT-FEE' $$,$$ VALUES (true,true,'SAR'::bpchar,true) $$,'project association derives Client and saves Project reporting currency');
SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='PROJECT-FEE'),1) $$,'project exchange submitted');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_currency_exchange('00000000-0000-0000-0000-000000008002',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='PROJECT-FEE'),2) $$,'project exchange approved');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='PROJECT-FEE' AND le.project_id=(SELECT id FROM app.projects WHERE name='Project 80') AND le.client_id=(SELECT client_id FROM app.projects WHERE name='Project 80')),6,'project and Client copied to every exchange ledger line');
SELECT results_eq($$ SELECT sum(reporting_debit_amount), sum(reporting_credit_amount) FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='PROJECT-FEE' AND le.line_no <= 4 $$,$$ VALUES (37.50::numeric,37.50::numeric) $$,'project conversion lines net zero in reporting currency');
SELECT results_eq($$ SELECT sum(le.credit_amount) FROM app.ledger_entries le JOIN app.ledger_accounts la ON la.id=le.ledger_account_id JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='PROJECT-FEE' AND la.financial_account_id=(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Fee 80') $$,$$ VALUES (1::numeric) $$,'project-associated fee decreases fee-paying account');

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_reversal('00000000-0000-0000-0000-000000008001',(SELECT ft.id FROM app.financial_transactions ft JOIN app.currency_exchanges ce ON ce.financial_event_id=ft.financial_event_id WHERE ce.reference='EX-002'),DATE '2026-08-05','reverse exchange','reverse exchange') $$,'existing full reversal can target posted exchange');
SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_reversal('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_events WHERE event_type='REVERSAL' AND description='reverse exchange'),1) $$,'exchange reversal submitted');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_reversal('00000000-0000-0000-0000-000000008002',(SELECT id FROM app.financial_events WHERE event_type='REVERSAL' AND description='reverse exchange'),2) $$,'exchange reversal approved');
SELECT is((SELECT count(*)::integer FROM app.ledger_entries le JOIN app.financial_transactions ft ON ft.id=le.financial_transaction_id JOIN app.financial_reversals fr ON fr.financial_event_id=ft.financial_event_id JOIN app.financial_transactions oft ON oft.id=fr.original_transaction_id JOIN app.currency_exchanges ce ON ce.financial_event_id=oft.financial_event_id WHERE ce.reference='EX-002'),4,'full reversal copies all four exchange lines');

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),500,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-04'),50,(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Fee 80'),DATE '2026-08-04',NULL,'NEG-OK') $$,'negative-balance policy permits oversized exchange draft');
SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='NEG-OK'),1) $$,'oversized exchange submitted');
SELECT lives_ok($$ SELECT * FROM public.server_owner_approve_currency_exchange('00000000-0000-0000-0000-000000008002',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='NEG-OK'),2) $$,'oversized exchange posts without sufficient-balance enforcement');
SELECT ok((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'))) < 0,'source account may become negative');
SELECT ok((SELECT balance FROM public.server_owner_financial_account_balance('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Fee 80'))) < 0,'fee-paying account may become negative');

SELECT lives_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),1,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-04'),0,NULL,DATE '2026-08-04',NULL,'REJECT-ME') $$,'rejection exchange draft created');
SELECT lives_ok($$ SELECT * FROM public.server_owner_submit_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='REJECT-ME'),1) $$,'rejection exchange submitted');
SELECT throws_ok($$ SELECT * FROM public.server_owner_reject_currency_exchange('00000000-0000-0000-0000-000000008002',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='REJECT-ME'),2,'') $$,'23514','Rejection reason is required.','blank rejection denied');
SELECT lives_ok($$ SELECT * FROM public.server_owner_reject_currency_exchange('00000000-0000-0000-0000-000000008002',(SELECT financial_event_id FROM app.currency_exchanges WHERE reference='REJECT-ME'),2,'private rejection') $$,'submitted exchange rejected');
SELECT lives_ok($$ SELECT * FROM public.server_owner_create_currency_exchange('00000000-0000-0000-0000-000000008001',(SELECT id FROM app.financial_accounts WHERE name='Exchange USD Source 80'),(SELECT id FROM app.financial_accounts WHERE name='Exchange SAR Destination 80'),1,(SELECT id FROM app.exchange_rates WHERE rate_date=DATE '2026-08-04'),0,NULL,DATE '2026-08-04',NULL,'REJECT-ME') $$,'replacement after rejection is allowed');
SELECT ok(NOT EXISTS (SELECT 1 FROM app.activity_logs WHERE action LIKE 'currency_exchange_%' AND (previous_values::text ILIKE '%private rejection%' OR new_values::text ILIKE '%private rejection%' OR metadata::text ILIKE '%private rejection%' OR previous_values::text ILIKE '%EX-002%' OR new_values::text ILIKE '%EX-002%' OR metadata::text ILIKE '%EX-002%')),'activity logs omit rejection text and raw references');
SELECT is_empty($$ SELECT table_name FROM information_schema.tables WHERE table_schema='app' AND table_name IN ('currency_exchange_uploads','currency_exchange_notifications','refunds') $$,'excluded uploads notifications and refunds remain absent');

SELECT * FROM finish();
ROLLBACK;
